INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','easy','mcq','What is the primary mechanism of action of penicillin antibiotics?','["A. Inhibition of transpeptidase (PBP) blocking peptidoglycan cross-linking","B. Inhibition of DNA gyrase","C. Binding to the 30S ribosomal subunit","D. Disruption of the bacterial cell membrane"]','A','Penicillins inhibit transpeptidase (penicillin-binding proteins, PBPs), which catalyse the final cross-linking step of peptidoglycan synthesis. This weakens the bacterial cell wall, leading to osmotic lysis. The antibiotic is bactericidal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','mcq','A patient with a known penicillin allergy requires antibiotic therapy. Which statement best describes the cross-reactivity risk between penicillins and cephalosporins?','["A. Cross-reactivity is less than 1-2%, and cephalosporins can generally be used with caution","B. Cross-reactivity is approximately 10-15%, so cephalosporins must always be avoided","C. Cross-reactivity is 50%, making cephalosporins absolutely contraindicated","D. There is no structural relationship between penicillins and cephalosporins"]','A','Studies show true immunological cross-reactivity between penicillins and cephalosporins is less than 1-2%. Both share a beta-lactam ring, but the side chains differ. Cephalosporins may be used with caution in penicillin-allergic patients unless the allergy was anaphylaxis to the same R1 side chain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','mcq','A patient with MSSA bacteraemia requires treatment. Which penicillin is most appropriate?','["A. Amoxicillin","B. Penicillin G","C. Nafcillin","D. Ampicillin"]','C','Nafcillin (and oxacillin) are penicillinase-resistant penicillins used specifically for MSSA (methicillin-susceptible Staphylococcus aureus) infections. They have a bulky side chain that prevents beta-lactamase access to the beta-lactam ring. MRSA is resistant to all penicillins including nafcillin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','easy','mcq','What is the role of clavulanate when combined with amoxicillin?','["A. It acts as a beta-lactamase inhibitor, protecting amoxicillin from enzymatic degradation","B. It enhances renal excretion of amoxicillin","C. It broadens coverage to include MRSA","D. It prevents nephrotoxicity of amoxicillin"]','A','Clavulanate is a beta-lactamase inhibitor. It binds irreversibly to beta-lactamase enzymes produced by resistant bacteria, protecting amoxicillin from destruction. Amoxicillin-clavulanate is useful for polymicrobial infections involving beta-lactamase-producing organisms such as Haemophilus influenzae and mixed oral/dental flora.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','hard','mcq','A 22-year-old presents with a diffuse maculopapular rash after receiving ampicillin for a sore throat. The monospot test is positive. What is the most accurate explanation?','["A. A non-allergic rash caused by interaction between ampicillin and Epstein-Barr virus","B. Type I IgE-mediated penicillin allergy requiring desensitisation","C. Stevens-Johnson syndrome triggered by the penicillin ring structure","D. Cross-reactivity with cephalosporins manifesting as delayed hypersensitivity"]','A','Ampicillin (and amoxicillin) cause a characteristic non-allergic maculopapular rash in approximately 80-100% of patients with infectious mononucleosis (EBV). This is NOT a true IgE-mediated allergy and does not indicate future penicillin allergy. The mechanism likely involves immune complex deposition in the context of EBV-altered immune responses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','mcq','Which correctly describes the spectrum difference between penicillin G and amoxicillin?','["A. Penicillin G is narrow spectrum (mainly Gram-positive/anaerobes) while amoxicillin has extended spectrum including some Gram-negatives","B. Penicillin G has broad spectrum while amoxicillin is narrow spectrum","C. Both have identical spectra but amoxicillin has better oral bioavailability only","D. Amoxicillin covers MRSA whereas penicillin G does not"]','A','Penicillin G is a narrow-spectrum agent effective primarily against Gram-positive cocci (streptococci, pneumococci), spirochetes, and some anaerobes. Amoxicillin is an aminopenicillin with extended spectrum that additionally covers Gram-negative organisms such as E. coli, H. influenzae, and Listeria. Neither covers MRSA.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','hard','mcq','Which beta-lactamase inhibitor is paired with piperacillin in the commonly used broad-spectrum IV combination?','["A. Clavulanate","B. Sulbactam","C. Tazobactam","D. Avibactam"]','C','Piperacillin-tazobactam (Pip-Tazo) is a widely used IV broad-spectrum combination where tazobactam inhibits beta-lactamases. Clavulanate is paired with amoxicillin or ticarcillin; sulbactam is paired with ampicillin; avibactam is a newer non-beta-lactam beta-lactamase inhibitor paired with ceftazidime.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','hard','mcq','Why are all penicillins (including nafcillin and methicillin) ineffective against MRSA?','["A. MRSA expresses an altered PBP2a with very low affinity for all beta-lactam antibiotics","B. MRSA produces a powerful beta-lactamase that destroys all penicillins","C. MRSA has an impermeable outer membrane that prevents penicillin entry","D. MRSA actively effluxes all beta-lactam antibiotics via MexAB-OprM"]','A','MRSA resistance is mediated by acquisition of the mecA gene encoding PBP2a, a modified penicillin-binding protein with markedly reduced affinity for all beta-lactam antibiotics including penicillinase-resistant penicillins. This is distinct from beta-lactamase production. Treatment options include vancomycin, linezolid, daptomycin, or ceftaroline.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','easy','mcq','What does a negative penicillin skin test most reliably predict?','["A. The patient has a very low risk of IgE-mediated anaphylaxis to penicillin","B. The patient will definitely develop a rash if given penicillin","C. The patient cannot receive any beta-lactam antibiotic","D. The patient has developed permanent tolerance to penicillin"]','A','Penicillin skin testing using major (penicilloyl-polylysine) and minor determinants has a negative predictive value greater than 97% for IgE-mediated (anaphylactic) reactions. A negative test means the risk of anaphylaxis is very low, allowing cautious administration. It does not rule out non-IgE reactions such as serum sickness or maculopapular rash.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Penicillins & Beta-lactams','medium','mcq','A patient with a dental abscess has a polymicrobial oral infection including beta-lactamase-producing anaerobes. Which agent is most appropriate?','["A. Penicillin G alone","B. Nafcillin","C. Amoxicillin-clavulanate","D. Oxacillin"]','C','Amoxicillin-clavulanate is the drug of choice for polymicrobial infections involving beta-lactamase-producing organisms including oral anaerobes (Prevotella, Fusobacterium). Clavulanate protects amoxicillin from enzymatic degradation. Penicillin G alone lacks coverage of beta-lactamase producers. Nafcillin and oxacillin are used specifically for MSSA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','easy','mcq','Which generation of cephalosporins is primarily used for surgical prophylaxis and offers excellent Gram-positive (including MSSA) coverage?','["A. First generation (e.g., cefazolin)","B. Second generation (e.g., cefuroxime)","C. Third generation (e.g., ceftriaxone)","D. Fourth generation (e.g., cefepime)"]','A','First-generation cephalosporins such as cefazolin have excellent Gram-positive coverage (MSSA, streptococci) and limited Gram-negative activity. Cefazolin is the standard antibiotic for surgical prophylaxis (skin flora coverage). It does not cover MRSA, Enterococcus, or most Gram-negative rods beyond E. coli and Klebsiella.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','mcq','A 35-year-old presents with bacterial meningitis and blood cultures grow Neisseria meningitidis. Which cephalosporin is the drug of choice due to excellent CSF penetration and Gram-negative coverage?','["A. Cefazolin","B. Cefuroxime","C. Ceftriaxone","D. Cefepime"]','C','Ceftriaxone is a third-generation cephalosporin with excellent CSF penetration and broad Gram-negative coverage, making it the drug of choice for bacterial meningitis caused by N. meningitidis and H. influenzae. It is also used for gonorrhoea (IM), Lyme disease, and typhoid fever.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','mcq','Which fifth-generation cephalosporin has the unique property of covering MRSA?','["A. Ceftazidime","B. Cefepime","C. Ceftaroline","D. Cefoxitin"]','C','Ceftaroline is a fifth-generation cephalosporin that binds PBP2a with sufficient affinity to be active against MRSA. It is the only beta-lactam with this property and is approved for community-acquired pneumonia and skin/soft tissue infections caused by MRSA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','hard','mcq','Why is cilastatin combined with imipenem in the clinical formulation imipenem-cilastatin?','["A. Cilastatin inhibits renal dehydropeptidase-I, preventing inactivation of imipenem in the proximal tubule","B. Cilastatin enhances CNS penetration of imipenem","C. Cilastatin acts as a beta-lactamase inhibitor protecting imipenem","D. Cilastatin reduces nephrotoxicity by chelating heavy metals"]','A','Imipenem is inactivated by renal dehydropeptidase-I (DHP-I) in the proximal tubule, generating nephrotoxic metabolites and reducing urinary drug levels. Cilastatin is a DHP-I inhibitor that prevents this inactivation, ensuring therapeutic urinary concentrations and reducing metabolite accumulation. Meropenem is stable to DHP-I and does not require cilastatin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','easy','mcq','Which carbapenem carries the highest risk of seizures and should be used with caution in patients with CNS disorders?','["A. Meropenem","B. Ertapenem","C. Imipenem","D. Doripenem"]','C','Imipenem carries the highest seizure risk among carbapenems, particularly at high doses or in patients with renal impairment or pre-existing CNS lesions. The mechanism involves antagonism of GABA-A receptors. Meropenem has a much lower seizure risk and is preferred for CNS infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','mcq','A patient in the ICU has an ESBL-producing Klebsiella pneumoniae bloodstream infection. Which antibiotic class is the treatment of choice?','["A. Third-generation cephalosporins","B. Fluoroquinolones","C. Carbapenems","D. Aminoglycosides"]','C','ESBL (extended-spectrum beta-lactamase)-producing organisms hydrolyse most penicillins and cephalosporins (including 3rd generation). Carbapenems are hydrolysis-resistant and are the drug of choice for serious ESBL infections. Aminoglycosides may have activity but are not first-line.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','hard','mcq','A patient with carbapenem-resistant Enterobacteriaceae (CRE) requires treatment. Which represents a last-resort therapy option?','["A. Imipenem-cilastatin alone","B. Meropenem alone","C. Ceftriaxone","D. Colistin or novel beta-lactam/beta-lactamase inhibitor combinations such as meropenem-vaborbactam"]','D','CRE (often expressing KPC, NDM, or OXA carbapenemases) are resistant to all carbapenems. Treatment options include colistin/polymyxin B, ceftazidime-avibactam, meropenem-vaborbactam, or imipenem-cilastatin-relebactam depending on the carbapenemase type. These are true last-resort agents with significant toxicity profiles.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','medium','mcq','Which cephalosporin is the preferred treatment for uncomplicated gonorrhoea in most current guidelines?','["A. Ceftriaxone IM","B. Cefazolin IM","C. Cefuroxime oral","D. Cefepime IV"]','A','Ceftriaxone 500 mg IM (or 1 g if weight greater than 150 kg) is the current recommended treatment for uncomplicated gonorrhoea (Neisseria gonorrhoeae). Resistance to fluoroquinolones and azithromycin has increased significantly. Ceftriaxone monotherapy is now preferred in many guidelines.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','hard','mcq','Second-generation cephalosporins such as cefoxitin and cefotetan are used for colorectal surgical prophylaxis. What additional coverage do they offer compared to first-generation agents?','["A. Anaerobic coverage including Bacteroides fragilis","B. MRSA coverage","C. Pseudomonas aeruginosa coverage","D. Extended Gram-positive coverage including Enterococcus"]','A','Cefoxitin and cefotetan (cephamycins, technically 2nd-generation) have activity against anaerobes including Bacteroides fragilis due to their 7-alpha-methoxy group that provides stability against anaerobic beta-lactamases. This makes them useful for colorectal and gynaecological surgical prophylaxis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Cephalosporins & Carbapenems','easy','mcq','Which fourth-generation cephalosporin has extended Gram-negative coverage including Pseudomonas aeruginosa?','["A. Ceftriaxone","B. Cefazolin","C. Cefepime","D. Cefadroxil"]','C','Cefepime is a fourth-generation cephalosporin with enhanced Gram-negative coverage including Pseudomonas aeruginosa, while retaining good Gram-positive activity. It is used for febrile neutropenia, hospital-acquired pneumonia, and serious Pseudomonas infections. It has good CNS penetration and is less susceptible to AmpC beta-lactamases than third-generation agents.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','easy','mcq','What is the mechanism of action of macrolide antibiotics such as azithromycin and erythromycin?','["A. Binding to the 50S ribosomal subunit and inhibiting translocation of the peptide chain","B. Inhibition of DNA gyrase","C. Binding to the 30S ribosomal subunit and blocking aminoacyl-tRNA binding","D. Inhibition of transpeptidase activity"]','A','Macrolides bind reversibly to the 23S rRNA of the 50S ribosomal subunit and inhibit translocation, the movement of the ribosome along the mRNA after peptide bond formation. This is bacteriostatic. The binding site is near that of chloramphenicol and clindamycin, so these drugs may compete if used together.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','mcq','A 30-year-old with community-acquired pneumonia and a penicillin allergy is treated as an outpatient. Which macrolide is most commonly used as the Z-pack monotherapy?','["A. Erythromycin","B. Clarithromycin","C. Azithromycin","D. Telithromycin"]','C','Azithromycin (Z-pack: 500 mg day 1, then 250 mg days 2-5) is widely used for outpatient community-acquired pneumonia, covering atypical organisms (Mycoplasma, Chlamydophila, Legionella). It has a long tissue half-life, once-daily dosing, and fewer GI side effects than erythromycin. However, increasing pneumococcal resistance is a concern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','mcq','Clarithromycin is an important component of which regimen used to eradicate Helicobacter pylori?','["A. PPI-based triple therapy (PPI + clarithromycin + amoxicillin or metronidazole)","B. Bismuth quadruple therapy","C. Sequential therapy using metronidazole and tetracycline alone","D. Monotherapy with clarithromycin alone"]','A','Clarithromycin-based triple therapy (PPI + clarithromycin + amoxicillin or metronidazole for 14 days) has been the standard H. pylori eradication regimen. Rising clarithromycin resistance (greater than 15% in many regions) has led to bismuth quadruple therapy being preferred in high-resistance areas.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','hard','mcq','Erythromycin is known for significant drug interactions. What is the primary pharmacokinetic mechanism responsible?','["A. Erythromycin inhibits CYP3A4, increasing plasma levels of co-administered drugs such as statins and warfarin","B. Erythromycin induces CYP3A4, reducing plasma levels of co-administered drugs","C. Erythromycin competes for renal tubular secretion with other drugs","D. Erythromycin inhibits P-glycoprotein in the gut wall"]','A','Erythromycin (and to a lesser extent clarithromycin) is a potent inhibitor of CYP3A4. This increases plasma levels of drugs metabolised by CYP3A4, including statins (risk of myopathy/rhabdomyolysis), warfarin (increased INR/bleeding), cyclosporine, and many others. Erythromycin also prolongs the QT interval and has prokinetic effects via motilin receptor agonism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','easy','mcq','What is the mechanism of action of tetracyclines?','["A. Bind to 30S ribosomal subunit and block binding of aminoacyl-tRNA to the A-site","B. Bind to 50S ribosome and inhibit peptide translocation","C. Inhibit cell wall synthesis by binding PBPs","D. Inhibit RNA polymerase"]','A','Tetracyclines bind reversibly to the 30S ribosomal subunit (specifically the 16S rRNA), blocking access of aminoacyl-tRNA to the A-site of the ribosome. This prevents addition of new amino acids to the growing peptide chain. The effect is bacteriostatic. Tetracyclines require active transport into susceptible bacteria and are broad-spectrum agents.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','mcq','A 25-year-old presents with erythema migrans after a tick bite in a Lyme-endemic area. Which antibiotic is the drug of choice for early Lyme disease in adults?','["A. Doxycycline","B. Azithromycin","C. Chloramphenicol","D. Amoxicillin-clavulanate"]','A','Doxycycline is the drug of choice for early Lyme disease (Borrelia burgdorferi) in adults and children over 8 years. It is also first-line for Rocky Mountain spotted fever (RMSF), atypical pneumonia, chlamydia, and malaria prophylaxis. Amoxicillin is an alternative in pregnancy or children under 8. Doxycycline should not be used in children under 8 or during pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','hard','mcq','A neonate develops grey discolouration, hypotension, abdominal distension, and cardiovascular collapse after receiving an antibiotic. Which drug is responsible and why?','["A. Azithromycin; QT prolongation-induced arrhythmia","B. Doxycycline; calcium chelation causing cardiac dysfunction","C. Chloramphenicol; grey baby syndrome due to immature hepatic conjugation and reduced renal excretion","D. Erythromycin; CYP3A4 inhibition causing accumulation of toxic neonatal metabolites"]','C','Chloramphenicol causes grey baby syndrome in neonates due to immature hepatic glucuronyl transferase enzyme and reduced renal excretion. The drug accumulates and causes cardiovascular collapse (grey cyanosis, hypotension, abdominal distension). Neonates and infants lack the capacity to conjugate and excrete chloramphenicol, requiring dose avoidance or strict monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','medium','mcq','Which antibiotic class is contraindicated in children under 8 years and in pregnant women due to teeth staining and bone growth inhibition?','["A. Macrolides","B. Fluoroquinolones","C. Aminoglycosides","D. Tetracyclines"]','D','All tetracyclines are contraindicated in children under 8 years and during pregnancy. They bind calcium in developing teeth (causing permanent yellow-brown discolouration and enamel hypoplasia) and can deposit in growing bones, causing growth retardation. They also cross the placenta and are potentially teratogenic. The exception is doxycycline for RMSF in young children when benefit outweighs risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','hard','mcq','Tigecycline is a glycylcycline derived from minocycline. What makes it useful against many multidrug-resistant organisms?','["A. It evades both efflux pump and ribosomal protection resistance mechanisms that confer tetracycline resistance","B. It inhibits CYP450 enzymes, reducing resistance metabolism","C. It has a unique mechanism targeting bacterial DNA gyrase","D. It is bactericidal unlike other tetracyclines"]','A','Tigecycline overcomes the two major tetracycline resistance mechanisms: efflux pump-mediated resistance (Tet B) and ribosomal protection proteins (Tet M). Its bulky 9-tert-butylglycylamido substituent sterically blocks efflux and improves ribosomal binding. Tigecycline has broad-spectrum activity including ESBL and CRE organisms, though it is not recommended for bacteraemia or hospital-acquired pneumonia due to clinical trial mortality signals.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Macrolides, Tetracyclines & Chloramphenicol','easy','mcq','What is the most feared idiosyncratic adverse effect of chloramphenicol that limits its systemic use?','["A. Aplastic anaemia","B. Nephrotoxicity","C. QT prolongation","D. Tendon rupture"]','A','Chloramphenicol can cause two types of bone marrow toxicity: dose-dependent reversible bone marrow suppression (common), and rare idiosyncratic aplastic anaemia (1 in 25,000-40,000 courses) which is irreversible and often fatal. Due to this risk, systemic chloramphenicol use in high-income countries is largely restricted to specific severe infections where alternatives are unavailable.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','easy','mcq','What is the mechanism of action of fluoroquinolone antibiotics?','["A. Inhibit bacterial DNA gyrase (topoisomerase II) and topoisomerase IV, preventing DNA replication and causing double-strand breaks","B. Inhibit 50S ribosome translocation","C. Inhibit transpeptidase and block peptidoglycan synthesis","D. Bind to 30S ribosome causing mRNA misreading"]','A','Fluoroquinolones inhibit bacterial type II topoisomerases: DNA gyrase (topoisomerase II, predominant target in Gram-negatives) and topoisomerase IV (predominant target in Gram-positives). These enzymes are required for DNA supercoiling and decatenation during replication. Inhibition causes double-strand DNA breaks, making fluoroquinolones bactericidal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','mcq','A patient develops Achilles tendon pain and swelling 2 weeks after starting ciprofloxacin for a UTI. What is the most likely explanation?','["A. Fluoroquinolone-associated tendinopathy due to collagen disruption and free radical generation in tenocytes","B. Ciprofloxacin-induced hyperuricaemia causing gout","C. Allergic reaction affecting musculotendinous structures","D. Ciprofloxacin inhibition of renal uric acid excretion"]','A','Fluoroquinolones cause tendinopathy and tendon rupture (most commonly the Achilles tendon) due to interference with collagen synthesis and free radical-mediated damage to tenocytes. Risk is increased in patients over 60, with concurrent corticosteroid use, and with renal failure. The FDA issued a black box warning. Quinolones should be discontinued immediately if tendon pain develops.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','mcq','Which fluoroquinolones are classified as respiratory quinolones appropriate for community-acquired pneumonia including atypical coverage?','["A. Levofloxacin and moxifloxacin","B. Ciprofloxacin and norfloxacin","C. Ofloxacin and enoxacin","D. Ciprofloxacin and levofloxacin"]','A','Levofloxacin and moxifloxacin are respiratory quinolones with enhanced activity against Streptococcus pneumoniae and atypical pathogens (Mycoplasma, Chlamydophila, Legionella). Ciprofloxacin has excellent Gram-negative coverage but poor Gram-positive activity and should NOT be used as monotherapy for community-acquired pneumonia. Moxifloxacin also has anaerobic activity but poor urinary excretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','hard','mcq','Aminoglycosides exhibit concentration-dependent killing. What is the clinical implication of this property for dosing?','["A. Once-daily dosing (high peak concentration) optimises bactericidal activity and may reduce accumulation-related toxicity","B. Multiple small daily doses are preferred to maintain continuous inhibitory levels","C. Aminoglycosides must be given continuously by IV infusion to be effective","D. Aminoglycosides require time-dependent killing like beta-lactams"]','A','Aminoglycosides exhibit concentration-dependent killing, meaning the higher the peak concentration relative to the MIC (Cmax/MIC ratio), the greater the bactericidal effect. Once-daily (extended-interval) dosing achieves high peak concentrations that maximise killing, while the post-antibiotic effect allows drug-free intervals that may reduce toxicity (nephrotoxicity correlates with trough accumulation in proximal tubular cells).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','easy','mcq','What are the two most clinically important toxicities of aminoglycosides such as gentamicin and tobramycin?','["A. Ototoxicity and nephrotoxicity","B. Hepatotoxicity and QT prolongation","C. Aplastic anaemia and grey baby syndrome","D. Tendon rupture and cartilage damage"]','A','Aminoglycosides accumulate in the proximal renal tubular cells (nephrotoxicity; usually reversible, manifests as non-oliguric renal failure) and in the endolymph of the inner ear (ototoxicity; cochlear and vestibular damage, often irreversible). Risk factors include prolonged therapy, high trough levels, concurrent nephrotoxins, and elderly patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','mcq','Ciprofloxacin is a first-line agent for which of the following infections?','["A. Typhoid fever (Salmonella typhi) and complicated UTIs caused by Gram-negative rods","B. Community-acquired pneumonia caused by S. pneumoniae","C. MRSA skin and soft tissue infections","D. Streptococcal pharyngitis"]','A','Ciprofloxacin has excellent Gram-negative activity and is first-line or a key alternative for typhoid fever (Salmonella typhi), complicated UTIs and pyelonephritis, anthrax prophylaxis and treatment, and Gram-negative rod infections. It is NOT appropriate for S. pneumoniae pneumonia (poor coverage) or MRSA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','hard','mcq','What is the pharmacokinetic/pharmacodynamic rationale for combining an aminoglycoside with a beta-lactam against Pseudomonas aeruginosa?','["A. Beta-lactams inhibit aminoglycoside efflux pumps in Pseudomonas","B. The combination prevents the nephrotoxic metabolites of aminoglycosides","C. Aminoglycosides inhibit beta-lactamase production in Pseudomonas","D. Beta-lactams disrupt cell wall integrity, enhancing aminoglycoside uptake and providing synergistic bactericidal killing"]','D','Beta-lactams disrupt the cell wall integrity of Pseudomonas, which enhances the uptake of aminoglycosides into the bacterial cell (aminoglycosides require an electrochemical gradient across the membrane for entry). This creates synergistic bactericidal activity. The combination also reduces the risk of selecting resistant mutants. Similar synergy occurs for Enterococcus (beta-lactam + gentamicin).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','hard','mcq','Fluoroquinolones are generally contraindicated in children and pregnant women primarily due to which adverse effect?','["A. Risk of QT prolongation and cardiac arrhythmias","B. Risk of grey baby syndrome","C. Risk of aplastic anaemia","D. Risk of cartilage damage and arthropathy in weight-bearing joints"]','D','Fluoroquinolones cause damage to developing cartilage in weight-bearing joints in juvenile animal studies, with erosion of articular cartilage. Although human evidence is less clear, fluoroquinolones are generally avoided in children and pregnant women. Ciprofloxacin is an exception for anthrax and certain other serious infections where benefit outweighs risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','medium','mcq','Which aminoglycoside is most commonly reserved for resistant organisms such as MDR Pseudomonas, due to its resistance to more aminoglycoside-modifying enzymes?','["A. Gentamicin","B. Tobramycin","C. Amikacin","D. Streptomycin"]','C','Amikacin is the aminoglycoside with the broadest resistance to aminoglycoside-modifying enzymes (acetyltransferases, nucleotidyltransferases, phosphotransferases) because its structure lacks many of the hydroxyl and amino groups that these enzymes target. It is reserved for resistant organisms including MDR Pseudomonas and Acinetobacter when gentamicin/tobramycin resistance has been demonstrated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Fluoroquinolones & Aminoglycosides','easy','mcq','Which antibiotic class is most strongly associated with Clostridioides difficile colitis risk?','["A. Aminoglycosides","B. Macrolides","C. Fluoroquinolones (especially gatifloxacin and moxifloxacin)","D. Glycopeptides"]','C','Fluoroquinolones, particularly gatifloxacin and moxifloxacin, are among the antibiotics most strongly associated with Clostridioides difficile infection (CDI) due to disruption of the normal colonic microbiome and selection of fluoroquinolone-resistant C. difficile ribotypes (especially ribotype 027). Clindamycin, broad-spectrum penicillins, and cephalosporins are also high risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','easy','mcq','What is the mechanism of action of vancomycin?','["A. Inhibits transpeptidase (PBP) similar to penicillin","B. Inhibits 50S ribosomal subunit translocation","C. Disrupts the bacterial cytoplasmic membrane by inserting into the lipid bilayer","D. Binds D-Ala-D-Ala terminus of peptidoglycan precursors, blocking transglycosylation and transpeptidation"]','D','Vancomycin is a glycopeptide that binds the D-Ala-D-Ala terminus of the peptidoglycan pentapeptide precursor (lipid II). This steric blockade prevents transglycosylation (polymerisation of peptidoglycan chains) and transpeptidation (cross-linking). It is bactericidal for Gram-positive organisms and does not penetrate the outer membrane of Gram-negatives.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','mcq','A patient develops flushing, erythema, and pruritus over the face and neck during rapid vancomycin infusion. What is the mechanism of this reaction?','["A. IgE-mediated type I hypersensitivity allergy to vancomycin","B. T-cell mediated delayed hypersensitivity reaction","C. Immune complex deposition causing type III hypersensitivity","D. Non-immune-mediated direct mast cell degranulation and histamine release due to rapid infusion rate (red man syndrome)"]','D','Red man syndrome is a non-allergic, infusion-rate-dependent reaction caused by direct mast cell degranulation and histamine release when vancomycin is infused too rapidly. It is not IgE-mediated allergy. Management includes slowing the infusion rate (at least 60 minutes) and pre-treating with antihistamines. It does not contraindicate future vancomycin use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','mcq','What vancomycin trough concentration is targeted for serious MRSA infections such as bacteraemia or pneumonia?','["A. 5-10 mg/L","B. 10-15 mg/L","C. 15-20 mg/L","D. Greater than 25 mg/L"]','C','For serious MRSA infections (bacteraemia, endocarditis, osteomyelitis, pneumonia), vancomycin trough concentrations of 15-20 mg/L are targeted to achieve AUC/MIC ratios associated with efficacy (AUC24/MIC greater than or equal to 400). Lower troughs (less than 10 mg/L) are associated with treatment failure. Newer guidance recommends AUC-guided monitoring over trough-only monitoring where available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','hard','mcq','What is the molecular mechanism of vancomycin resistance in VRE (vancomycin-resistant Enterococcus)?','["A. VRE produces a vancomycin-specific beta-lactamase that destroys the antibiotic","B. VRE has reduced outer membrane permeability that prevents vancomycin entry","C. VRE expresses an efflux pump that rapidly removes vancomycin from the cytoplasm","D. VRE modifies the terminal D-Ala-D-Ala to D-Ala-D-Lac, reducing vancomycin binding affinity 1000-fold"]','D','VanA and VanB resistance in VRE involves ligases that substitute D-lactate (D-Lac) for D-alanine at the C-terminal position of the peptidoglycan pentapeptide, creating D-Ala-D-Lac. The single oxygen-for-nitrogen substitution eliminates a critical hydrogen bond, reducing vancomycin binding affinity by approximately 1000-fold. Treatment options for VRE include linezolid and daptomycin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','mcq','Which of the following is a clinically important drug interaction with linezolid?','["A. Linezolid inhibits CYP3A4, increasing levels of co-administered drugs","B. Linezolid potentiates warfarin anticoagulation by inhibiting CYP2C9","C. Linezolid induces renal clearance of vancomycin","D. Linezolid is a monoamine oxidase inhibitor and can cause serotonin syndrome when combined with SSRIs or tramadol"]','D','Linezolid is a weak, reversible monoamine oxidase inhibitor (MAOI). When combined with serotonergic drugs (SSRIs, SNRIs, tricyclics, tramadol, meperidine), it can precipitate serotonin syndrome (hyperthermia, agitation, clonus, diaphoresis, tremor). Linezolid should be avoided with these drugs or used with extreme caution with close monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','hard','mcq','Daptomycin is not effective for pneumonia caused by Gram-positive organisms. What is the pharmacological explanation?','["A. Daptomycin is inactivated by pulmonary surfactant (phosphatidylglycerol), which sequesters the drug","B. Daptomycin does not penetrate alveolar capillaries due to its large molecular weight","C. Daptomycin is metabolised by alveolar macrophages before reaching bacteria","D. Daptomycin requires high calcium concentrations absent in lung tissue"]','A','Daptomycin mechanism involves calcium-dependent insertion into the bacterial cytoplasmic membrane, causing membrane depolarisation. In the lung, pulmonary surfactant (particularly phosphatidylglycerol) binds and inactivates daptomycin, preventing it from reaching the bacterial membrane. This is why daptomycin must NOT be used for pneumonia despite its excellent MRSA activity in other body sites.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','easy','mcq','Linezolid belongs to which antibiotic class and what is its primary mechanism?','["A. Glycopeptide; binds D-Ala-D-Ala on peptidoglycan precursors","B. Macrolide; inhibits 50S translocation","C. Streptogramin; inhibits both 50S binding and peptide elongation","D. Oxazolidinone; binds 50S ribosomal subunit and prevents formation of the 70S initiation complex"]','D','Linezolid is an oxazolidinone antibiotic. It binds to the 23S rRNA of the 50S ribosomal subunit at a unique site and prevents formation of the 70S initiation complex (blocks joining of 30S and 50S subunits, blocking the start of translation). This is a unique mechanism with no cross-resistance to other antibiotic classes. It is bacteriostatic against staphylococci and enterococci, but bactericidal against streptococci.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','hard','mcq','A patient on linezolid for VRE endocarditis develops thrombocytopaenia after 3 weeks of therapy. What is the likely mechanism?','["A. Immune thrombocytopaenic purpura triggered by linezolid as a hapten","B. Linezolid competes with thrombopoietin for receptor binding on megakaryocytes","C. Linezolid induces autoantibodies against platelet surface antigens","D. Linezolid inhibits mitochondrial protein synthesis, causing dose-dependent myelosuppression"]','D','Linezolid inhibits mitochondrial protein synthesis (via the same 50S ribosomal target) in mammalian cells. With prolonged use (greater than 2 weeks), this causes reversible myelosuppression, most commonly thrombocytopaenia but also anaemia and leucopaenia. Weekly full blood counts are recommended. Lactic acidosis and peripheral/optic neuropathy can also occur with prolonged use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','medium','mcq','Teicoplanin is a glycopeptide antibiotic. What is its main clinical advantage over vancomycin?','["A. It covers VRE in addition to MRSA","B. It has broad-spectrum Gram-negative coverage","C. It has no nephrotoxicity or ototoxicity","D. It can be given once daily due to its long half-life, offering outpatient treatment options"]','D','Teicoplanin is structurally related to vancomycin with a similar mechanism (D-Ala-D-Ala binding), spectrum, and indications. Its clinical advantage is a long elimination half-life (40-70 hours), allowing once-daily administration and suitability for outpatient/home IV therapy. It also has lower rates of nephrotoxicity than vancomycin and does not cause red man syndrome.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Glycopeptides & Oxazolidinones','easy','mcq','For which infection is vancomycin given orally rather than intravenously, and why?','["A. MRSA bacteraemia; oral bioavailability reaches therapeutic blood levels","B. MRSA endocarditis; oral vancomycin is equivalent to IV for endocarditis","C. VRE urinary tract infection; oral dosing achieves adequate urinary levels","D. Clostridioides difficile colitis; oral vancomycin acts locally in the gut lumen as it is not absorbed systemically"]','D','Oral vancomycin is used for C. difficile colitis because it acts locally within the bowel lumen. Vancomycin is not absorbed from the intact GI tract, so oral administration achieves high concentrations in the colon where C. difficile resides, while systemic levels remain negligible. For systemic MRSA infections, IV administration is required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','easy','mcq','What is the mechanism of action of amphotericin B?','["A. Inhibits ergosterol synthesis by blocking CYP450 C14-alpha-demethylase","B. Inhibits squalene epoxidase, depleting ergosterol","C. Inhibits beta-glucan synthase, disrupting cell wall synthesis","D. Binds ergosterol in the fungal cell membrane, forming pores that cause membrane leakage and cell death"]','D','Amphotericin B binds ergosterol (the principal sterol in fungal cell membranes) with high affinity, forming transmembrane pores/channels. This causes membrane depolarisation, leakage of intracellular ions (K+, Mg2+), and cell death. It has broad-spectrum fungicidal activity. Toxicity is related to binding to cholesterol in human cell membranes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','mcq','A patient with invasive aspergillosis requires treatment. Which azole is considered the drug of choice?','["A. Fluconazole","B. Itraconazole","C. Voriconazole","D. Posaconazole"]','C','Voriconazole is the drug of choice for invasive aspergillosis (IA), supported by landmark randomised trials showing superiority over amphotericin B deoxycholate. It has excellent oral bioavailability, CSF penetration, and broad activity against Aspergillus species. Fluconazole has no activity against Aspergillus. Posaconazole is used for prophylaxis in neutropenic patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','mcq','Why is liposomal amphotericin B preferred over conventional amphotericin B deoxycholate in many clinical situations?','["A. Liposomal formulation improves antifungal spectrum to cover resistant Candida species","B. Liposomal formulation eliminates the need for electrolyte monitoring","C. Liposomal formulation allows oral administration","D. Liposomal formulation significantly reduces nephrotoxicity and infusion-related reactions while maintaining efficacy"]','D','Liposomal amphotericin B (AmBisome) preferentially delivers amphotericin B to sites of infection while reducing uptake by renal tubular cells, significantly reducing nephrotoxicity. Infusion-related fevers and rigors are also substantially reduced. The antifungal spectrum is unchanged. Pre-hydration with normal saline still helps reduce nephrotoxicity with lipid formulations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','easy','mcq','What is the primary mechanism of action of azole antifungals such as fluconazole, voriconazole, and itraconazole?','["A. Bind ergosterol and form membrane pores","B. Inhibit squalene epoxidase in the ergosterol biosynthesis pathway","C. Inhibit beta-1,3-glucan synthase in the fungal cell wall","D. Inhibit fungal CYP450 C14-alpha-demethylase, blocking conversion of lanosterol to ergosterol"]','D','Azoles inhibit fungal cytochrome P450 enzyme 14-alpha-lanosterol demethylase (Erg11/CYP51), which catalyses a critical step in ergosterol biosynthesis. This depletes ergosterol and causes accumulation of toxic methylated sterols, disrupting membrane function. Azoles are fungistatic for most yeasts. They also inhibit human CYP450 enzymes, causing significant drug interactions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','hard','mcq','Flucytosine (5-FC) is used in combination with amphotericin B for cryptococcal meningitis. What is its mechanism of action?','["A. It inhibits fungal ergosterol synthesis by blocking CYP450 demethylase","B. It binds ergosterol and creates membrane pores synergistically with amphotericin B","C. It inhibits beta-glucan synthase in the fungal cell wall","D. It is converted intracellularly to 5-fluorouracil, which inhibits thymidylate synthase and disrupts fungal RNA and DNA synthesis"]','D','Flucytosine is taken up by fungi via cytosine permease and deaminated intracellularly to 5-fluorouracil (5-FU) by cytosine deaminase (absent in mammalian cells). 5-FU is then phosphorylated to 5-FUTP (incorporated into RNA, disrupting protein synthesis) and 5-FdUMP (inhibits thymidylate synthase, blocking DNA synthesis). Resistance develops rapidly if used as monotherapy, hence combination with amphotericin B for cryptococcal meningitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','mcq','Which antifungal class inhibits beta-1,3-glucan synthase and is active against Candida and Aspergillus but NOT Cryptococcus?','["A. Polyenes (amphotericin B)","B. Azoles (fluconazole, voriconazole)","C. Echinocandins (caspofungin, micafungin, anidulafungin)","D. Allylamines (terbinafine)"]','C','Echinocandins inhibit beta-1,3-glucan synthase, an enzyme essential for synthesis of beta-glucan (a major structural polysaccharide in fungal cell walls). This is fungicidal for Candida and fungistatic for Aspergillus. Cryptococcus neoformans has a capsule-rich cell wall with little beta-glucan and is intrinsically resistant to echinocandins. Echinocandins are first-line for invasive Candida infections in critically ill patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','hard','mcq','A neutropenic patient is started on posaconazole. What is the primary indication for posaconazole in this context?','["A. Treatment of established Candida bloodstream infection","B. Secondary prophylaxis of oral candidiasis in HIV patients","C. Treatment of cryptococcal meningitis as monotherapy","D. Primary antifungal prophylaxis against Aspergillus and rare moulds in high-risk neutropenic patients"]','D','Posaconazole has broad-spectrum coverage including Aspergillus, Mucorales (Rhizopus, Mucor), and Fusarium; moulds that voriconazole and fluconazole miss. It is recommended for antifungal prophylaxis in high-risk neutropenic patients (acute myeloid leukaemia induction chemotherapy, stem cell transplant with graft-versus-host disease) where invasive mould infections carry high mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','easy','mcq','Terbinafine is used to treat dermatophyte infections such as onychomycosis. What is its mechanism?','["A. Inhibits CYP450 C14-demethylase, reducing ergosterol production","B. Inhibits beta-glucan synthase in dermatophyte cell walls","C. Binds ergosterol and forms membrane pores","D. Inhibits squalene epoxidase, causing squalene accumulation toxic to fungi"]','D','Terbinafine inhibits squalene epoxidase (an enzyme in the ergosterol biosynthesis pathway), leading to accumulation of squalene which is toxic to fungal cells and depletion of ergosterol. It is fungicidal for dermatophytes. Terbinafine is the drug of choice for onychomycosis with superior cure rates over azoles. Oral terbinafine can cause hepatotoxicity (monitor LFTs).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','medium','mcq','A patient with chronic mucocutaneous candidiasis fails fluconazole therapy. What is the most likely resistance mechanism?','["A. Mutation in FKS1 gene encoding beta-glucan synthase","B. Overexpression of squalene epoxidase bypassing azole blockade","C. Loss of cytosine permease preventing drug uptake","D. Upregulation of CDR1/CDR2 efflux pumps or mutation in ERG11 reducing azole binding affinity"]','D','Azole resistance in Candida most commonly involves: (1) upregulation of ABC efflux transporters (CDR1, CDR2) that pump fluconazole out of the cell, (2) point mutations in ERG11 (encodes the azole target, CYP51) reducing drug binding affinity, or (3) upregulation of ERG11 (overexpression of target). FKS1 mutations cause echinocandin resistance.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antifungals','hard','mcq','Griseofulvin is an oral antifungal used for dermatophyte infections. What is its unique mechanism of action?','["A. Inhibits ergosterol synthesis via CYP450 C14-demethylase inhibition","B. Binds ergosterol and creates membrane pores similar to amphotericin B","C. Inhibits squalene epoxidase, depleting ergosterol","D. Disrupts fungal microtubule assembly by binding tubulin, preventing mitosis and nuclear division"]','D','Griseofulvin binds to tubulin and disrupts microtubule polymerisation, inhibiting fungal cell mitosis. It also interferes with intracellular transport along microtubules. Griseofulvin accumulates in keratin-rich tissues (skin, hair, nails), making it useful for dermatophyte infections. It induces CYP450 enzymes and can reduce the efficacy of oral contraceptives.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','easy','mcq','What is the mechanism of action of nucleoside reverse transcriptase inhibitors (NRTIs) such as tenofovir and emtricitabine?','["A. They bind non-competitively to reverse transcriptase and alter its conformation","B. They inhibit HIV protease, preventing maturation of viral polyproteins","C. They inhibit HIV integrase, preventing viral DNA integration into the host genome","D. They are phosphorylated intracellularly, competitively inhibit reverse transcriptase, and act as chain terminators when incorporated into viral DNA"]','D','NRTIs are prodrugs that require intracellular phosphorylation to the active triphosphate form. They competitively inhibit HIV reverse transcriptase and, when incorporated into the growing viral DNA chain, act as chain terminators (lacking the 3-OH group required for phosphodiester bond formation). They are the backbone of all HIV regimens. Key examples: tenofovir (TDF/TAF), emtricitabine (FTC), abacavir (ABC), lamivudine (3TC).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','mcq','Before initiating abacavir in an HIV-positive patient, which genetic test is mandatory?','["A. HLA-B*1502 testing for Stevens-Johnson syndrome risk","B. G6PD testing for haemolytic anaemia risk","C. CYP2D6 genotyping for abacavir metabolism","D. HLA-B*5701 testing for abacavir hypersensitivity syndrome"]','D','Abacavir hypersensitivity syndrome (AHS) is a potentially life-threatening multi-organ reaction that occurs in 5-8% of patients carrying HLA-B*5701 allele. Symptoms include fever, rash, GI symptoms, and respiratory symptoms, appearing within 6 weeks. HLA-B*5701 testing is mandatory before abacavir initiation. If positive, abacavir is absolutely contraindicated. Rechallenge after a hypersensitivity reaction can be fatal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','mcq','Which class of antiretroviral agents is now preferred as the anchor drug in first-line HIV regimens due to excellent efficacy, tolerability, and high barrier to resistance?','["A. Non-nucleoside reverse transcriptase inhibitors (NNRTIs) such as efavirenz","B. Protease inhibitors (PIs) such as ritonavir-boosted darunavir","C. Integrase strand transfer inhibitors (INSTIs) such as dolutegravir or bictegravir","D. Fusion inhibitors such as enfuvirtide"]','C','INSTIs (dolutegravir, bictegravir, raltegravir) have become the preferred anchor drugs in HIV therapy due to high efficacy, rapid viral suppression, high barrier to resistance (especially dolutegravir and bictegravir), and excellent tolerability. Current WHO guidelines recommend TDF/FTC/DTG as the preferred first-line regimen globally. Weight gain is a noted adverse effect of INSTIs, particularly dolutegravir.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','hard','mcq','What is the mechanism of action of HIV protease inhibitors such as ritonavir, lopinavir, and darunavir?','["A. Competitively inhibit reverse transcriptase preventing RNA-to-DNA conversion","B. Block viral fusion by binding gp41 and preventing conformational change","C. Inhibit HIV integrase, preventing viral DNA integration into the CD4+ cell nucleus","D. Block the HIV protease enzyme that cleaves the gag-pol polyprotein, resulting in immature non-infectious viral particles"]','D','HIV protease is an aspartyl protease that cleaves the Gag and Gag-Pol polyprotein precursors into mature structural proteins and enzymes. Protease inhibitors competitively bind the active site, preventing cleavage. The result is production of immature, non-infectious virions. PIs are metabolised by CYP3A4; ritonavir is used at low boosting doses to inhibit CYP3A4 and increase levels of co-administered PIs (pharmacokinetic boosting).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','mcq','Efavirenz is an NNRTI associated with which distinctive CNS side effects?','["A. Peripheral neuropathy and optic neuritis","B. Extrapyramidal side effects resembling Parkinsonism","C. Serotonin syndrome when combined with SSRIs","D. Vivid dreams, insomnia, depression, and dizziness, most prominent in the first weeks of therapy"]','D','Efavirenz causes CNS side effects in up to 50% of patients: vivid/disturbing dreams, insomnia, dizziness, difficulty concentrating, and mood changes (depression, psychosis, suicidal ideation in rare cases). These are most pronounced in the first 2-4 weeks and typically improve. Efavirenz is also teratogenic and is avoided in the first trimester of pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','hard','mcq','Maraviroc is a CCR5 antagonist used in HIV therapy. Which prerequisite test must be performed before initiating maraviroc?','["A. HLA-B*5701 testing to rule out hypersensitivity","B. CYP3A4 phenotyping to determine appropriate dosing","C. G6PD testing to rule out haemolytic anaemia","D. HIV tropism testing to confirm CCR5-tropic (R5) virus and rule out CXCR4-tropic or dual/mixed-tropic virus"]','D','Maraviroc blocks the CCR5 co-receptor on CD4+ T cells, preventing R5-tropic HIV from binding and entering. If the patient virus uses CXCR4 or both co-receptors (dual/mixed tropic), maraviroc will be ineffective. A phenotypic tropism assay (Trofile) or genotypic tropism testing must be performed before prescribing maraviroc.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','easy','mcq','The current WHO-recommended first-line antiretroviral regimen for treatment-naive adults is which of the following?','["A. Zidovudine + lamivudine + nevirapine","B. Tenofovir + emtricitabine + efavirenz","C. Tenofovir + emtricitabine (or lamivudine) + dolutegravir","D. Abacavir + lamivudine + lopinavir-ritonavir"]','C','WHO guidelines (2021 onwards) recommend TDF + 3TC or FTC + DTG (dolutegravir) as the preferred first-line ART regimen. Dolutegravir-based regimens have higher efficacy, fewer side effects, and a higher genetic barrier to resistance than efavirenz-based regimens. TAF (tenofovir alafenamide) is preferred where available as it has less nephrotoxicity and bone density loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','hard','mcq','NNRTIs such as nevirapine and efavirenz have a low genetic barrier to resistance. Which single mutation most commonly confers high-level NNRTI resistance?','["A. M184V mutation in reverse transcriptase","B. K65R mutation in reverse transcriptase","C. K103N mutation in reverse transcriptase","D. D30N mutation in protease"]','C','The K103N (lysine to asparagine at codon 103) substitution in reverse transcriptase is the most common NNRTI resistance mutation. It confers high-level resistance to nevirapine, efavirenz, and delavirdine by preventing drugs from binding the NNRTI-binding pocket. K103N does not affect NRTI activity. Second-generation NNRTIs (rilpivirine, etravirine) have activity against some K103N-harbouring viruses.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','medium','mcq','Enfuvirtide (T20) is a fusion inhibitor used for salvage therapy in HIV. What is its mechanism?','["A. It binds CD4 receptors on T cells, preventing HIV attachment","B. It blocks CCR5 co-receptor engagement with gp120","C. It binds the HR1 region of HIV gp41, preventing the conformational change required for membrane fusion","D. It inhibits HIV reverse transcriptase in a non-competitive manner"]','C','Enfuvirtide is a 36-amino acid peptide that binds to the heptad repeat 1 (HR1) domain of HIV-1 gp41. This prevents the HR1-HR2 hairpin fold necessary for membrane fusion between HIV and the host CD4+ cell. It requires subcutaneous injection twice daily. Injection site reactions are the most common adverse effect. It is reserved for salvage therapy due to cost and resistance development.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — HIV','hard','mcq','Long-term use of tenofovir disoproxil fumarate (TDF) is associated with which specific adverse effects that prompted development of tenofovir alafenamide (TAF)?','["A. Hepatotoxicity and lactic acidosis","B. Peripheral neuropathy and pancreatitis","C. Nephrotoxicity (proximal tubular dysfunction/Fanconi syndrome) and decreased bone mineral density","D. Hypersensitivity reactions and Stevens-Johnson syndrome"]','C','TDF is associated with nephrotoxicity (proximal renal tubular dysfunction, occasionally Fanconi syndrome) and decreased bone mineral density (due to increased renal phosphate wasting). TAF delivers tenofovir more efficiently to lymphoid cells at lower plasma concentrations, reducing renal and bone toxicity by approximately 80%. TAF is preferred in patients with renal impairment or osteoporosis risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','easy','mcq','What is the mechanism of action of acyclovir against herpes simplex virus?','["A. Acyclovir inhibits viral DNA polymerase non-competitively","B. Acyclovir blocks HSV attachment to host cell surface receptors","C. Acyclovir is phosphorylated by viral thymidine kinase then host kinases to acyclovir triphosphate, which competitively inhibits and chain-terminates viral DNA polymerase","D. Acyclovir inhibits herpesvirus protease preventing capsid assembly"]','C','Acyclovir is a guanosine analogue requiring three phosphorylation steps. The critical first step is performed by HSV-encoded thymidine kinase (viral TK), which phosphorylates acyclovir much more efficiently than host TK; this selectivity accounts for the drug safety profile. Acyclovir triphosphate competitively inhibits HSV DNA polymerase and is incorporated into the viral DNA chain, acting as an obligate chain terminator.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','mcq','Ganciclovir is used to treat CMV retinitis in immunocompromised patients. How does it differ from acyclovir mechanistically, and what is its main toxicity?','["A. Ganciclovir inhibits CMV protease; main toxicity is nephrotoxicity","B. Ganciclovir blocks CMV integrase; main toxicity is hepatotoxicity","C. Ganciclovir is phosphorylated by CMV-encoded UL97 kinase (not viral TK), making it active against CMV; main toxicity is myelosuppression","D. Ganciclovir binds CMV tegument proteins; main toxicity is neurotoxicity"]','C','Ganciclovir is phosphorylated to ganciclovir monophosphate by the CMV-encoded phosphotransferase UL97 (CMV lacks thymidine kinase). This is why acyclovir has minimal CMV activity. Ganciclovir triphosphate inhibits CMV DNA polymerase (UL54). Major toxicity is myelosuppression (neutropaenia, thrombocytopaenia), more severe than acyclovir. Valganciclovir is the oral prodrug with improved bioavailability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','mcq','Foscarnet is used for CMV and HSV infections resistant to standard antivirals. What is its mechanism and main toxicity?','["A. Foscarnet is a nucleoside analogue that terminates viral DNA chains; main toxicity is myelosuppression","B. Foscarnet is a pyrophosphate analogue that directly inhibits viral DNA polymerase without requiring phosphorylation; main toxicities are nephrotoxicity and electrolyte disturbances","C. Foscarnet inhibits viral neuraminidase; main toxicity is bronchospasm","D. Foscarnet inhibits viral integrase; main toxicity is hypersensitivity reactions"]','B','Foscarnet (phosphonoformic acid) is an inorganic pyrophosphate analogue. It directly inhibits viral DNA polymerase (and HIV reverse transcriptase) at the pyrophosphate binding site, without requiring activation by viral kinases. This makes it active against acyclovir-resistant HSV (TK-deficient mutants) and ganciclovir-resistant CMV (UL97 mutants). Major toxicities are nephrotoxicity and electrolyte disturbances (hypocalcaemia, hypomagnesaemia). Hydration is essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','easy','mcq','Oseltamivir (Tamiflu) is used to treat influenza. What is its mechanism and when must it be initiated for maximum benefit?','["A. It inhibits influenza haemagglutinin, preventing viral attachment; initiate at any time","B. It inhibits influenza neuraminidase, preventing viral release from infected cells; initiate within 48 hours of symptom onset","C. It inhibits influenza RNA polymerase complex; initiate within 72 hours","D. It blocks the M2 ion channel, preventing viral uncoating; initiate within 24 hours"]','B','Oseltamivir inhibits neuraminidase, the viral surface enzyme that cleaves sialic acid residues to allow release of newly formed virions from infected cells. Without neuraminidase, virions aggregate at the cell surface and cannot spread. It must be initiated within 48 hours of symptom onset for maximum clinical benefit. It is active against both influenza A and B. Zanamivir (inhaled) has the same mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','hard','mcq','A liver transplant patient with chronic hepatitis B requires long-term antiviral suppression. Which agent is preferred due to its high barrier to resistance?','["A. Lamivudine","B. Adefovir","C. Entecavir","D. Telbivudine"]','C','Entecavir and tenofovir (TDF/TAF) have the highest barriers to resistance among nucleos(t)ide analogues for chronic hepatitis B. Entecavir resistance is rare (less than 1% in treatment-naive patients at 5 years). Lamivudine has a very high resistance rate (greater than 70% at 5 years due to YMDD mutations). Tenofovir also has an excellent resistance profile and is another first-line choice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','mcq','Sofosbuvir-based direct-acting antiviral (DAA) regimens have revolutionised hepatitis C treatment. What is sofosbuvir mechanism?','["A. It inhibits HCV NS3/4A serine protease, blocking polyprotein processing","B. It is a uridine nucleotide analogue that inhibits HCV NS5B RNA-dependent RNA polymerase, acting as a chain terminator","C. It inhibits HCV NS5A replication complex assembly and RNA replication","D. It blocks HCV entry by inhibiting viral envelope protein E2 interaction with CD81"]','B','Sofosbuvir is a NS5B polymerase inhibitor. It is a prodrug metabolised intracellularly to sofosbuvir triphosphate, which acts as a competitive substrate and chain terminator of the HCV RNA-dependent RNA polymerase (NS5B). Combined with NS5A inhibitors such as ledipasvir or velpatasvir, sofosbuvir-based regimens achieve greater than 95% sustained virological response rates across all HCV genotypes in 8-12 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','hard','mcq','Ribavirin is absolutely contraindicated in pregnancy. In which viral infections has it been used clinically?','["A. HIV and CMV infections","B. RSV (inhaled, in severe bronchiolitis) and chronic HCV (with interferon or certain DAA regimens)","C. Influenza A exclusively","D. HSV encephalitis and VZV pneumonitis"]','B','Ribavirin is a guanosine analogue with broad antiviral activity. It is used as inhaled ribavirin for severe RSV bronchiolitis in immunocompromised patients. It was the backbone of interferon-based HCV regimens and is still used in some DAA-based combinations for difficult-to-treat HCV genotypes. It causes haemolytic anaemia (dose-dependent), is teratogenic in both partners, and requires two forms of contraception during and for 6 months after therapy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','easy','mcq','Valacyclovir is the prodrug of acyclovir. What is the key pharmacokinetic advantage of valacyclovir over oral acyclovir?','["A. Valacyclovir requires no renal dose adjustment unlike acyclovir","B. Valacyclovir has markedly improved oral bioavailability (54-70%) compared to acyclovir (15-20%), allowing less frequent dosing","C. Valacyclovir penetrates the CNS better than acyclovir for HSV encephalitis treatment","D. Valacyclovir is not renally excreted and therefore safer in renal impairment"]','B','Valacyclovir is the L-valyl ester prodrug of acyclovir. After oral absorption, it is rapidly hydrolysed by intestinal and hepatic valacyclovir hydrolase to acyclovir. Bioavailability is 54-70% versus 15-20% for oral acyclovir, producing plasma acyclovir levels approaching those achieved with IV acyclovir. This allows less frequent dosing. Renal dose adjustment is still required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','hard','mcq','IV acyclovir can cause nephrotoxicity via crystalline nephropathy. What is the mechanism and how is it prevented?','["A. Acyclovir directly damages proximal tubular cells; prevented by probenecid co-administration","B. Acyclovir precipitates as crystals in renal tubules when urine concentrations are high; prevented by slow infusion (over 1 hour) and adequate IV hydration","C. Acyclovir causes immune-mediated interstitial nephritis; prevented by corticosteroid premedication","D. Acyclovir chelates renal calcium, causing tubular dysfunction; prevented by calcium gluconate infusion"]','B','Acyclovir has limited aqueous solubility and can precipitate in renal tubular lumens when urinary concentrations are high (particularly with rapid bolus IV administration or hypovolaemia). This causes tubular obstruction and acute kidney injury. Prevention requires slow IV infusion (over at least 1 hour), adequate saline hydration, and avoiding rapid boluses. Dose adjustment is essential in renal impairment.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antivirals — Other','medium','mcq','Which antiviral is used for prophylaxis and treatment of CMV disease in solid organ transplant recipients, and what is its primary adverse effect?','["A. Acyclovir; renal crystalline nephropathy","B. Valganciclovir (prodrug of ganciclovir); myelosuppression (neutropaenia)","C. Foscarnet; hypocalcaemia and seizures","D. Cidofovir; hepatotoxicity"]','B','Valganciclovir is the oral prodrug of ganciclovir with high bioavailability (approximately 60%), used for CMV prophylaxis and treatment in transplant recipients and HIV patients with CMV retinitis. It is preferred over IV ganciclovir for oral therapy. The primary dose-limiting adverse effect is myelosuppression: neutropaenia (most common), thrombocytopaenia, and anaemia. Regular CBC monitoring is essential during therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','easy','mcq','According to Ghana Standard Treatment Guidelines 2017, which antimalarial is the first-line treatment for uncomplicated Plasmodium falciparum malaria?','["A. Chloroquine + primaquine","B. Artemether-lumefantrine (AL)","C. Quinine monotherapy","D. Mefloquine"]','B','The Ghana STG 2017 specifies artemether-lumefantrine (Coartem) as the first-line treatment for uncomplicated P. falciparum malaria. It is an artemisinin-based combination therapy (ACT) given as a 6-dose regimen over 3 days (twice daily with fatty food to enhance lumefantrine absorption). ACTs rapidly reduce parasite burden via the artemisinin component, with lumefantrine providing longer-acting clearance of residual parasites.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','easy','mcq','According to Ghana STG 2017, which drug is first-line for severe and complicated malaria in all age groups?','["A. Quinine IV","B. Artesunate IV or IM","C. Artemether-lumefantrine oral","D. Chloroquine IV"]','B','The Ghana STG 2017 designates artesunate IV (or IM when IV is not available) as the first-line treatment for severe and complicated malaria. IV artesunate is superior to quinine in reducing mortality in severe malaria (AQUAMAT and SEAQUAMAT trials). Quinine IV is reserved for situations where artesunate is unavailable. After clinical improvement, patients are stepped down to oral ACT (artemether-lumefantrine).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','mcq','What is the mechanism by which artemisinin and its derivatives kill malaria parasites?','["A. They inhibit dihydrofolate reductase, blocking folate synthesis in the parasite","B. They are activated by intraparasitic haem iron, generating cytotoxic free radicals that alkylate parasite proteins and cause oxidative damage","C. They inhibit haem polymerisation in the parasite food vacuole causing haem accumulation","D. They block the plasmodium chloroquine resistance transporter (CRT) efflux pump"]','B','Artemisinins contain an endoperoxide bridge that is cleaved by haem iron within the parasite digestive vacuole. This generates reactive oxygen species (carbon-centred and oxygen-centred radicals) that alkylate and damage critical parasite proteins. The rapid action against ring-stage parasites leads to rapid parasite clearance. This mechanism is entirely distinct from chloroquine (haem polymerisation inhibition).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','mcq','Chloroquine is still effective for treating infections with which Plasmodium species?','["A. Chloroquine-resistant P. falciparum in sub-Saharan Africa","B. P. vivax, P. ovale, P. malariae, and chloroquine-sensitive P. falciparum","C. P. knowlesi and P. vivax only","D. P. falciparum in all regions globally"]','B','Chloroquine remains effective against P. vivax, P. ovale, P. malariae, and the rare chloroquine-sensitive P. falciparum strains. However, in most of sub-Saharan Africa (including Ghana), almost all P. falciparum is chloroquine-resistant due to mutations in the CRT gene, leading to efflux of chloroquine from the parasite food vacuole. Chloroquine-resistant P. vivax is also increasingly reported in Papua New Guinea and parts of Asia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','hard','mcq','Why must G6PD testing be performed before prescribing primaquine for P. vivax malaria?','["A. G6PD-deficient patients metabolise primaquine to toxic levels causing hepatotoxicity","B. Primaquine generates oxidative metabolites that cause haemolytic anaemia in G6PD-deficient red blood cells, which lack the capacity to regenerate NADPH","C. G6PD deficiency leads to primaquine resistance, requiring higher nephrotoxic doses","D. Primaquine inhibits G6PD activity, worsening the deficiency and causing thrombocytopaenia"]','B','Primaquine is metabolised to quinone compounds that generate reactive oxygen species. In normal red blood cells, G6PD regenerates NADPH which maintains glutathione in its reduced form to neutralise oxidative stress. G6PD-deficient red blood cells cannot regenerate NADPH, making them susceptible to oxidative haemolysis when exposed to primaquine. Haemolytic anaemia can be severe and life-threatening. G6PD screening is mandatory before primaquine therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','mcq','Primaquine is essential in treating P. vivax and P. ovale malaria because it is the only drug with activity against which parasite stage?','["A. Blood-stage ring-form parasites","B. Liver hypnozoites, preventing relapse","C. Sexual stage gametocytes only","D. Merozoites released from the liver into the bloodstream"]','B','P. vivax and P. ovale form dormant liver-stage parasites called hypnozoites that can reactivate weeks to months (or years) after the initial infection, causing relapse. Primaquine is the only licensed drug with activity against hypnozoites (radical cure). Without primaquine, blood-stage treatment (e.g., chloroquine) will clear the acute episode but relapse will occur. Primaquine also has gametocytocidal activity against P. falciparum.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','hard','mcq','A patient has severe malaria and artesunate IV is unavailable. Which parenteral agent is the next best option, and what side effect cluster should be monitored?','["A. Chloroquine IV; hypotension and arrhythmias","B. Quinine IV (or IM); cinchonism (tinnitus, hearing impairment, visual disturbances) and severe hypoglycaemia","C. Mefloquine IV; neuropsychiatric symptoms","D. Artemether IM; hepatotoxicity and renal failure"]','B','When artesunate is unavailable, quinine is the alternative for severe malaria. Parenteral quinine requires cardiac monitoring (QT prolongation, arrhythmias). Cinchonism (tinnitus, high-frequency hearing loss, blurred vision, headache, nausea) is dose-related and common. Severe hypoglycaemia is a life-threatening complication (especially in pregnancy) due to quinine-stimulated insulin secretion. The loading dose protocol must be used carefully.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','medium','mcq','What is the mechanism of action of chloroquine against malaria parasites?','["A. Chloroquine inhibits dihydrofolate reductase in the parasite, blocking folate synthesis","B. Chloroquine concentrates in the parasite food vacuole and inhibits haem polymerase, causing accumulation of toxic free haem","C. Chloroquine alkylates parasite DNA via an endoperoxide mechanism","D. Chloroquine inhibits the CRT transporter, trapping drug and preventing efflux"]','B','Malaria parasites digest haemoglobin in their food vacuole, releasing haem (ferriprotoporphyrin IX). Free haem is toxic and is normally detoxified by polymerisation to insoluble haemozoin (malaria pigment). Chloroquine accumulates in the food vacuole (due to proton-trapping) and inhibits haem polymerisation, causing lethal accumulation of toxic free haem. Resistance involves mutations in the CRT gene enabling efflux of chloroquine from the vacuole.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','hard','mcq','Which group of patients should NOT receive mefloquine for malaria prophylaxis or treatment, and why?','["A. Patients with G6PD deficiency, due to risk of haemolytic anaemia","B. Patients with a history of psychiatric illness or seizure disorders, due to risk of severe neuropsychiatric side effects","C. Pregnant women in the second trimester, due to teratogenicity","D. Patients with renal impairment, due to accumulation of toxic metabolites"]','B','Mefloquine causes significant neuropsychiatric adverse effects including anxiety, depression, hallucinations, psychosis, nightmares, dizziness, and seizures. These can occur weeks to months after completing therapy and may be persistent. The FDA added a black box warning. Mefloquine is contraindicated in patients with a history of psychiatric illness (depression, anxiety, psychosis, schizophrenia) or seizure disorders.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antimalarials','easy','mcq','Doxycycline is used for malaria prophylaxis. Which mechanism makes it effective against Plasmodium?','["A. It inhibits haem polymerisation in the parasite food vacuole","B. It inhibits protein synthesis at the parasite apicoplast 70S ribosome, impairing organelle function","C. It generates free radicals activated by parasite iron","D. It inhibits dihydropteroate synthase in the folate synthesis pathway"]','B','Tetracyclines including doxycycline target the apicoplast (a plastid-like organelle in Plasmodium), inhibiting 70S ribosomal function and apicoplast protein synthesis. The delayed antiparasitic effect (delayed death phenomenon) means doxycycline is generally used for prophylaxis or in combination with quinine for treatment, rather than monotherapy. It is effective for chemoprophylaxis in areas with chloroquine and mefloquine resistance.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','easy','mcq','What is the mechanism of action of metronidazole against anaerobic organisms and protozoa?','["A. It inhibits cell wall synthesis by blocking peptidoglycan cross-linking","B. It is reduced by anaerobic ferredoxin-linked electron transport to form cytotoxic radical intermediates that cause DNA strand breaks","C. It inhibits the 50S ribosomal subunit, preventing protein synthesis","D. It disrupts the cytoplasmic membrane by binding membrane phospholipids"]','B','Metronidazole is selectively toxic to anaerobic organisms because its nitro group is reduced by low-redox ferredoxin electron transport systems (present in anaerobes and some protozoa). The reduced intermediate (nitroradical anion) reacts with DNA, causing strand breaks and inhibiting DNA synthesis. Aerobic organisms cannot generate the necessary reducing conditions. Metronidazole is used for amoebiasis, giardiasis, trichomoniasis, BV, C. difficile, and anaerobic bacterial infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','mcq','A patient on metronidazole reports severe nausea and flushing after drinking alcohol. What is the explanation for this interaction?','["A. Metronidazole induces CYP2E1, increasing ethanol metabolism to toxic acetaldehyde at higher rates","B. Metronidazole inhibits aldehyde dehydrogenase (ALDH), causing acetaldehyde accumulation, a disulfiram-like reaction","C. Ethanol inhibits metronidazole absorption, requiring higher doses that are toxic","D. Metronidazole and alcohol compete for protein binding, increasing free drug concentrations"]','B','Metronidazole inhibits aldehyde dehydrogenase (ALDH), the enzyme responsible for oxidising acetaldehyde (the first metabolite of ethanol) to acetic acid. Acetaldehyde accumulates, causing flushing, nausea, vomiting, headache, palpitations, and hypotension; identical to the disulfiram reaction. Patients must avoid alcohol during and for 48 hours after completing metronidazole therapy. Tinidazole has a similar interaction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','mcq','Albendazole is used to treat a wide range of helminth infections. What is its mechanism?','["A. It increases membrane permeability to calcium, causing worm paralysis","B. It inhibits tubulin polymerisation in helminths, disrupting microtubule function, glucose uptake, and cellular transport","C. It blocks glutamate-gated chloride channels, causing worm hyperpolarisation and paralysis","D. It depolarises the worm neuromuscular junction, causing spastic paralysis"]','B','Albendazole binds selectively to beta-tubulin in helminths (higher affinity than mammalian tubulin), inhibiting microtubule polymerisation. This disrupts microtubule-dependent processes including intracellular transport, cell division, and glucose uptake in the worm. The active metabolite is albendazole sulphoxide. Albendazole has broad-spectrum activity against nematodes, tapeworms, and is used for neurocysticercosis and echinococcosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','hard','mcq','Praziquantel is the drug of choice for schistosomiasis. What is its mechanism of action?','["A. It inhibits tubulin polymerisation, disrupting schistosome microtubules","B. It increases membrane permeability to calcium ions in the schistosome, causing muscle contraction, tetanic paralysis, and tegument vacuolisation","C. It inhibits fumarate reductase in the schistosome, blocking energy metabolism","D. It activates glutamate-gated chloride channels, causing schistosome hyperpolarisation and paralysis"]','B','Praziquantel acts on schistosome voltage-gated Ca2+ channels, causing rapid influx of calcium ions. This leads to immediate muscular tetanic contraction (worm paralysis) followed by tegument disruption (vacuolisation and blebbing), exposing the worm surface to immune attack. Praziquantel is effective against all Schistosoma species, most tapeworms and flukes. Adult Taenia solium cysts (neurocysticercosis) require albendazole with dexamethasone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','easy','mcq','Ivermectin is used to treat onchocerciasis (river blindness) and strongyloidiasis. What is its mechanism?','["A. It inhibits tubulin polymerisation in parasitic worms","B. It binds glutamate-gated chloride channels (GluCl) unique to invertebrates, causing hyperpolarisation and irreversible paralysis of worm nerve and muscle","C. It inhibits haem polymerisation in the parasite food vacuole","D. It causes calcium influx and spastic paralysis in the worm"]','B','Ivermectin binds selectively to glutamate-gated chloride channels (GluCl) expressed in invertebrate nerve and muscle cells. This causes increased chloride permeability, leading to hyperpolarisation and paralysis of the parasite. GluCl channels are absent in mammals, accounting for the drug selectivity. Ivermectin kills microfilariae and inhibits larval development but does not kill adult worms effectively. It also treats scabies and head lice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','mcq','Which antiparasitic drug is the treatment of choice for lymphatic filariasis caused by Wuchereria bancrofti?','["A. Albendazole alone","B. Ivermectin alone","C. Diethylcarbamazine (DEC)","D. Praziquantel"]','C','Diethylcarbamazine (DEC) is the drug of choice for lymphatic filariasis (W. bancrofti, Brugia malayi, B. timori). It is microfilaricidal and has some macrofilaricidal activity. DEC alters microfilarial surface properties, facilitating immune-mediated killing. Mass drug administration programmes typically combine DEC + albendazole (or ivermectin + albendazole in onchocerciasis co-endemic areas). DEC is contraindicated in onchocerciasis (risk of severe Mazzotti reaction).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','hard','mcq','Mebendazole is preferred over albendazole for purely intestinal helminth infections in some settings. Why?','["A. Mebendazole has broader activity against tissue-invasive helminths than albendazole","B. Mebendazole has poor systemic absorption, concentrating in the gut lumen, which is advantageous for intestinal helminths and reduces systemic side effects","C. Mebendazole is active against adult tapeworm scolex while albendazole is not","D. Mebendazole has a longer half-life requiring single-dose therapy whereas albendazole requires 3 days"]','B','Mebendazole shares the same mechanism as albendazole (beta-tubulin inhibition) but has very poor systemic absorption (less than 10%). This means it achieves high luminal concentrations ideal for intestinal helminths (Ascaris, Trichuris, hookworm, pinworm) but has minimal systemic exposure, reducing hepatic and CNS side effects. Albendazole is better absorbed and preferred for tissue-invasive infections (neurocysticercosis, echinococcosis).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','hard','mcq','A child presents with perianal itching worse at night. Sellotape test reveals Enterobius vermicularis (pinworm) eggs. Which drug is appropriate and what is its mechanism?','["A. Praziquantel; increases calcium influx causing worm paralysis","B. Ivermectin; activates glutamate-gated chloride channels causing worm hyperpolarisation","C. Pyrantel pamoate; depolarising neuromuscular blocker causing spastic paralysis of the worm","D. Metronidazole; generates cytotoxic radicals causing parasite DNA damage"]','C','Pyrantel pamoate is a nicotinic acetylcholine receptor agonist that causes depolarising neuromuscular blockade in helminths, resulting in spastic paralysis. The paralysed worm is expelled by intestinal peristalsis. It is available OTC, well-tolerated (poorly absorbed), and is first-line for pinworm (Enterobius) and also effective for Ascaris (roundworm). The whole household should be treated simultaneously, with retreatment in 2 weeks to prevent reinfection.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','medium','mcq','Tinidazole is closely related to metronidazole. What is its main clinical advantage?','["A. Tinidazole covers aerobic bacteria whereas metronidazole does not","B. Tinidazole has a longer half-life (approximately 12-14 hours) allowing single-dose or shorter-course treatment for giardiasis and trichomoniasis","C. Tinidazole does not cause a disulfiram-like reaction with alcohol","D. Tinidazole is safe in the first trimester of pregnancy unlike metronidazole"]','B','Tinidazole is a 2nd-generation nitroimidazole with a longer half-life (12-14 hours vs. 6-8 hours for metronidazole), allowing once-daily dosing or single-dose treatment for some infections (trichomoniasis: 2 g single dose; giardiasis: 2 g single dose). It has similar spectrum and the same disulfiram-like alcohol interaction. Like metronidazole, it should be avoided in the first trimester of pregnancy. Many patients report better GI tolerability.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Infectious Diseases','Pharmacology','Antiparasitics & Anthelmintics','easy','mcq','Niclosamide is used specifically for which type of parasitic infection and via what mechanism?','["A. Blood flukes (schistosomiasis); increases calcium permeability causing tetanic paralysis","B. Tapeworm (cestode) intestinal infections; inhibits glucose uptake and oxidative phosphorylation in tapeworms","C. Roundworm (nematode) infections; depolarises the neuromuscular junction","D. Malaria; inhibits haem polymerisation in the food vacuole"]','B','Niclosamide is active against intestinal tapeworms (Taenia saginata, T. solium, Diphyllobothrium latum, Hymenolepis nana). It inhibits oxidative phosphorylation (uncouples mitochondrial electron transport) and inhibits glucose uptake in tapeworms, leading to worm death. It is poorly absorbed from the gut, concentrating its action in the intestinal lumen. For T. solium infections, purging after treatment is recommended to prevent autoinfection with released eggs causing cysticercosis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
